#!/usr/bin/env python3
"""SR-CHURN-CUT 3: generated files are regenerated by CI from main, never carried in a PR diff.

One registry (`generated_paths.json`) lists every machine-owned path, so the CI guard, the cockpit's patch-id
computation (SR-CHURN-CUT 4) and the builders' commit step all read the same list. This module also holds the
derivation of the one KĀLA-YANTRA generated file that is not a node-compiled overlay: CLOSURE_v3.json, a pure
function of plan_model.json + ACCEPTANCE_ROOTS (fleet/kyclosure.py compute).

  generated_paths.py list                     one generated path/prefix per line
  git diff --name-only A B | generated_paths.py filter     the names that are NOT generated (patch-id input)
  generated_paths.py check --base SHA         PR guard: refuses a diff that carries a generated path or edits a pin shard
  generated_paths.py refresh                  rewrite the locally derivable committed copies (cockpit/main checkout only)
Exit: 0 ok · 1 refused (findings on stderr)
"""
from __future__ import annotations
import argparse
import json
import os
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[3]
REGISTRY = Path(__file__).with_name('generated_paths.json')
FLEET = ROOT / '00_ARCHITECTURE/briefs/kalayantra/fleet'
MODEL = '00_ARCHITECTURE/control/kalayantra/plan_model.json'
CLOSURE = '00_ARCHITECTURE/control/kalayantra/CLOSURE_v3.json'
SHARD_DIR = '00_ARCHITECTURE/briefs/kalayantra/fleet/tests/executor_pin_shards/'


def load(path: Path = REGISTRY) -> dict:
    doc = json.loads(path.read_text(encoding='utf-8'))
    if doc.get('schema') != 'ky.generated_paths/1':
        raise ValueError(f'{path}: unexpected schema {doc.get("schema")!r}')
    return doc


def is_generated(path: str, reg: dict | None = None) -> bool:
    reg = reg or load()
    if path in reg['paths']:
        return True
    return (any(path.startswith(p) for p in reg['prefixes'])
            and not any(path.startswith(p) for p in reg['not_generated_prefixes'])
            and '/__tests__/' not in path and not path.endswith(('.test.ts', '.test.tsx')))


def generated_in(paths, reg: dict | None = None) -> list[str]:
    reg = reg or load()
    return [p for p in paths if is_generated(p, reg)]


def closure_bytes(root: Path = ROOT) -> bytes:
    """The closure of the model's own roots file, rendered twice; the two renders must be byte-identical."""
    sys.path.insert(0, str(FLEET))
    try:
        import kyclosure
    finally:
        sys.path.remove(str(FLEET))
    model = json.loads((root / MODEL).read_text(encoding='utf-8'))
    roots = json.loads((root / model['control_plane']['triage']['roots']).read_text(encoding='utf-8'))
    first, second = (kyclosure.render(kyclosure.compute(model, roots)) for _ in range(2))
    if first != second:
        raise ValueError('closure is not deterministic')
    return first


def write_closure(root: Path = ROOT) -> Path:
    target = root / CLOSURE
    target.write_bytes(closure_bytes(root))
    return target


def _git(root: Path, *args: str) -> str:
    return subprocess.check_output(['git', '-C', str(root), *args], env={**os.environ, 'GIT_OPTIONAL_LOCKS': '0'}, text=True)


def shard_violations(changes: list[tuple[str, str]]) -> list[str]:
    """Pin shards are append-only: a shard that exists at the base is reviewed history and is never modified, renamed or removed."""
    return [f'executor pin shard {path} is merged history; add a new shard instead of {status}-ing it'
            for status, path in changes if path.startswith(SHARD_DIR) and not status.startswith('A')]


def diff_changes(root: Path, base: str, head: str = 'HEAD') -> list[tuple[str, str]]:
    out = []
    for line in _git(root, 'diff', '--name-status', '--no-renames', f'{base}...{head}').splitlines():
        status, _, path = line.partition('\t')
        out.append((status, path))
    return out


def check(root: Path, base: str, head: str = 'HEAD') -> list[str]:
    changes = diff_changes(root, base, head)
    errors = [f'machine-owned path carried in the diff (CI regenerates it from main): {p}'
              for p in generated_in([p for _, p in changes], load(root / 'platform/scripts/governance/generated_paths.json'))]
    return errors + shard_violations(changes)


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('mode', choices=['list', 'filter', 'check', 'refresh'])
    ap.add_argument('--base')
    ap.add_argument('--head', default='HEAD')
    ns = ap.parse_args(argv)
    if ns.mode == 'list':
        reg = load()
        print('\n'.join(reg['paths'] + reg['prefixes']))
        return 0
    if ns.mode == 'filter':
        reg = load()
        for line in sys.stdin.read().splitlines():
            if line and not is_generated(line, reg):
                print(line)
        return 0
    if ns.mode == 'refresh':
        print(write_closure())
        return 0
    if not ns.base:
        ap.error('check needs --base')
    errors = check(ROOT, ns.base, ns.head)
    for error in errors:
        print(error, file=sys.stderr)
    return 1 if errors else 0


if __name__ == '__main__':
    try:
        sys.exit(main())
    except (ValueError, OSError, subprocess.CalledProcessError) as exc:
        print(f'generated_paths refused: {exc}', file=sys.stderr)
        sys.exit(1)
